import * as React from 'react';

// @interlace/streak v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/streak
// What changed since: https://ds.interlace.tools/c/streak#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — Streak
 *
 * A player's run of days: the count, a line on where today stands, and a
 * strip of recent days, each marked played, rested, missed or still open.
 * Rest days come from a `RestRule` (weekdays and dates that never break a
 * run), so a habit does not punish a day off. The arithmetic lives in
 * `streak-model.ts` and is exported, so a server can store and check the
 * same numbers this shows.
 *
 * ## Anatomy
 *
 *   Streak                         (div — data-slot="streak", data-status=played|pending|resting|none)
 *     ├─ p                         (data-slot="streak-count": the number and its unit)
 *     ├─ p                         (data-slot="streak-status": where today stands)
 *     ├─ ol                        (data-slot="streak-days", labelled)
 *     │   └─ li × length           (data-slot="streak-day", data-state=played|rest|missed|open|future)
 *     └─ p                         (data-slot="streak-best")
 *
 *   variant="compact" renders one inline chip (data-slot="streak") with the
 *   count and a full sentence for assistive tech, for a header or a toolbar.
 *
 * ## Never colour alone
 *
 * A played day is a filled mark with a check, a rest day a dashed ring with
 * a moon, a missed day an empty ring, today an open ring with a dot. Each
 * day also carries its full date and state as text for screen readers.
 *
 * ## Motion
 *
 * Today's check scales in once when it first appears (CSS `@starting-style`,
 * 250ms, `motion-safe:` only). Nothing else moves.
 *
 * ## Server first
 *
 * No hooks, no state: it renders on the server. Pass `today` (a day key in
 * the player's time zone) when the server's clock is not the player's; the
 * fallback reads the clock in `timeZone`.
 *
 * ## MIN_VIEWPORT — 320
 *
 * Seven 28px marks with their gaps fit a 288px column; they grow to 32px
 * from `xs`.
 *
 * | Rule | Concept                   | Where in this file                                    |
 * | ---- | ------------------------- | ----------------------------------------------------- |
 * | R4   | Extends native el         | `React.ComponentProps<'div'>`                         |
 * | R6   | data-slot per part        | streak / -count / -status / -days / -day / -best      |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                     |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const                  |
 * | R19  | Tokens only               | primary, muted-foreground, input, ring                |
 * | R26  | A11y                      | labelled list; every day as text; status as a sentence |
 */

import { Check, Flame, Moon } from 'lucide-react';

import { cn } from '@/lib/utils';
import { dayKey, dayKeyToDate, type DayKey } from '@/components/ui/games/daily';
import {
  streakDays,
  summarizeStreak,
  type RestRule,
  type StreakDayState,
  type StreakStatus,
} from '@/components/ui/games/streak-model';

export const MIN_VIEWPORT = 320 as const;

interface StreakLabels {
  /** After the number. @default 'day streak' */
  unit?: string;
  /** One sentence per status. */
  status?: Partial<Record<StreakStatus, string>>;
  /** The best run. @default n => `Best: ${n} days` */
  best?: (best: number) => string;
  /** Names the strip for assistive tech. @default 'Recent days' */
  days?: string;
  /** Each day's state, read after its date. */
  state?: Partial<Record<StreakDayState, string>>;
}

type StreakProps = Omit<React.ComponentProps<'div'>, 'children'> & {
  /** Every day the player played, as day keys. Order and duplicates do not matter. */
  played: readonly DayKey[];
  /** Today, in the player's time zone. @default dayKey(new Date(), timeZone) */
  today?: DayKey;
  /** IANA time zone for the fallback `today`. */
  timeZone?: string;
  /** Days that never break a run. */
  rest?: RestRule;
  /** Days in the strip, ending today. @default 7 */
  length?: number;
  /** Days after today to show as still to come. @default 0 */
  after?: number;
  /** `full` shows the strip; `compact` is one inline chip. @default 'full' */
  variant?: 'full' | 'compact';
  /** Show the best run under the strip. @default true */
  showBest?: boolean;
  /** BCP 47 locale for numbers and day names. @default the runtime's */
  locale?: string;
  labels?: StreakLabels;
};

const STATUS: Record<StreakStatus, string> = {
  played: 'Played today. See you tomorrow.',
  pending: 'Play today to keep your streak.',
  resting: 'Rest day. Your streak is safe.',
  none: 'Play today to start a streak.',
};

const STATE: Record<StreakDayState, string> = {
  played: 'played',
  rest: 'rest day',
  missed: 'missed',
  open: 'not played yet',
  future: 'still to come',
};

const MARK =
  'relative grid size-7 xs:size-8 shrink-0 place-items-center rounded-full [&_svg]:size-3.5 xs:[&_svg]:size-4';

function DayMark({ state, today }: { state: StreakDayState; today: boolean }) {
  switch (state) {
    case 'played':
      return (
        <span className={cn(MARK, 'bg-primary text-primary-foreground')}>
          <Check
            aria-hidden
            strokeWidth={3}
            className={cn(
              today &&
                'motion-safe:transition-[scale,opacity] motion-safe:duration-(--duration-medium) motion-safe:ease-enter motion-safe:starting:scale-50 motion-safe:starting:opacity-0',
            )}
          />
        </span>
      );
    case 'rest':
      return (
        <span className={cn(MARK, 'border-muted-foreground text-muted-foreground border-2 border-dashed')}>
          <Moon aria-hidden />
        </span>
      );
    case 'open':
      return (
        <span className={cn(MARK, 'border-primary border-2')}>
          <span aria-hidden className="bg-primary size-1.5 rounded-full" />
        </span>
      );
    case 'future':
      return <span className={cn(MARK, 'border-input border border-dashed')} />;
    default:
      return <span className={cn(MARK, 'border-input border-2')} />;
  }
}

function Streak({
  played,
  today: todayProp,
  timeZone,
  rest,
  length = 7,
  after = 0,
  variant = 'full',
  showBest = true,
  locale,
  labels,
  className,
  ...props
}: StreakProps) {
  const today = todayProp ?? dayKey(new Date(), timeZone);
  const summary = summarizeStreak(played, today, rest);
  const unit = labels?.unit ?? 'day streak';
  const status = labels?.status?.[summary.status] ?? STATUS[summary.status];
  const count = new Intl.NumberFormat(locale).format(summary.current);

  if (variant === 'compact') {
    return (
      <div
        data-slot="streak"
        data-variant="compact"
        data-status={summary.status}
        data-min-viewport={String(MIN_VIEWPORT)}
        className={cn(
          'border-border bg-card text-card-foreground inline-flex min-h-8 items-center gap-1.5 rounded-full border px-3 text-sm font-semibold tabular-nums',
          className,
        )}
        {...props}
      >
        <Flame
          aria-hidden
          className={cn('size-4', summary.status === 'played' ? 'text-primary' : 'text-muted-foreground')}
        />
        <span aria-hidden>{count}</span>
        <span className="sr-only">
          {count} {unit}. {status}
        </span>
      </div>
    );
  }

  const days = streakDays(played, today, { length, after, rest });
  const short = new Intl.DateTimeFormat(locale, { weekday: 'narrow', timeZone: 'UTC' });
  const long = new Intl.DateTimeFormat(locale, {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    timeZone: 'UTC',
  });
  const best = labels?.best ?? ((n: number) => `Best: ${new Intl.NumberFormat(locale).format(n)} ${n === 1 ? 'day' : 'days'}`);

  return (
    <div
      data-slot="streak"
      data-variant="full"
      data-status={summary.status}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('grid gap-3', className)}
      {...props}
    >
      <p data-slot="streak-count" className="flex items-baseline gap-2">
        <span className="font-heading text-section leading-none font-semibold tabular-nums">{count}</span>
        <span className="text-muted-foreground text-sm font-medium">{unit}</span>
      </p>
      <p data-slot="streak-status" className="text-sm">
        {status}
      </p>
      <ol
        data-slot="streak-days"
        aria-label={labels?.days ?? 'Recent days'}
        className="xs:gap-2 flex flex-wrap gap-1.5"
      >
        {days.map((d) => (
          <li
            key={d.day}
            data-slot="streak-day"
            data-state={d.state}
            data-today={d.today ? '' : undefined}
            aria-current={d.today ? 'date' : undefined}
            className="grid justify-items-center gap-1"
          >
            <span
              aria-hidden
              className={cn(
                'text-xs leading-none',
                d.today ? 'text-foreground font-semibold' : 'text-muted-foreground',
              )}
            >
              {short.format(dayKeyToDate(d.day))}
            </span>
            <DayMark state={d.state} today={d.today} />
            <span className="sr-only">
              {long.format(dayKeyToDate(d.day))}: {labels?.state?.[d.state] ?? STATE[d.state]}
            </span>
          </li>
        ))}
      </ol>
      {showBest && summary.best > 0 ? (
        <p data-slot="streak-best" className="text-muted-foreground text-sm">
          {best(summary.best)}
        </p>
      ) : null}
    </div>
  );
}
Streak.displayName = 'Streak';

export { Streak };
export type { StreakProps, StreakLabels };

export type DayKey = string;

const DAY_MS = 86_400_000;
const KEY_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * The calendar day `date` falls on in `timeZone` (an IANA name such as
 * `"Europe/Paris"`). Without a time zone, the runtime's own is used, which on
 * a server is usually UTC: pass the player's zone when the page renders on
 * one.
 */
export function dayKey(date: Date | number = Date.now(), timeZone?: string): DayKey {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(typeof date === 'number' ? new Date(date) : date);
  const part = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return `${part.year}-${part.month}-${part.day}`;
}

/** True when `value` is a well-formed day key for a real date. */
export function isDayKey(value: unknown): value is DayKey {
  if (typeof value !== 'string') return false;
  const m = KEY_RE.exec(value);
  if (!m) return false;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return d.getUTCFullYear() === +m[1] && d.getUTCMonth() === +m[2] - 1 && d.getUTCDate() === +m[3];
}

function toUtc(key: DayKey): number {
  const m = KEY_RE.exec(key);
  if (!m) throw new RangeError(`Not a day key: "${key}" (expected YYYY-MM-DD)`);
  return Date.UTC(+m[1], +m[2] - 1, +m[3]);
}

/** Midnight UTC of the day, as a Date: the safe way to format a key with Intl. */
export function dayKeyToDate(key: DayKey): Date {
  return new Date(toUtc(key));
}

/** The key `days` after `key` (negative goes back). */
export function addDays(key: DayKey, days: number): DayKey {
  return new Date(toUtc(key) + days * DAY_MS).toISOString().slice(0, 10);
}

/** Whole days from `from` to `to`; negative when `to` is earlier. */
export function daysBetween(from: DayKey, to: DayKey): number {
  return Math.round((toUtc(to) - toUtc(from)) / DAY_MS);
}

/** Day of the week, 0 for Sunday to 6 for Saturday, as `Date.getDay` counts. */
export function weekdayOf(key: DayKey): number {
  return new Date(toUtc(key)).getUTCDay();
}

/**
 * The puzzle's number: 1 on `firstDay`, 2 the day after. Before `firstDay`
 * it is 0 or less, which a caller should treat as "not started".
 */
export function puzzleNumber(key: DayKey, firstDay: DayKey): number {
  return daysBetween(firstDay, key) + 1;
}

/** FNV-1a, 32-bit: a small, stable string hash for seeds. */
export function hashString(value: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/**
 * A seeded generator of numbers in [0, 1) (mulberry32). Good enough to deal
 * puzzles and shuffle answers the same way everywhere; not for anything
 * secret.
 */
export function seededRandom(seed: number | string): () => number {
  let a = typeof seed === 'string' ? hashString(seed) : seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4_294_967_296;
  };
}

/** A copy of `items` in a seeded order (Fisher–Yates). */
export function seededShuffle<T>(items: readonly T[], seed: number | string): T[] {
  const out = items.slice();
  const random = seededRandom(seed);
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j] as T, out[i] as T];
  }
  return out;
}

export interface DailyIndexOptions {
  /** The day puzzle 1 ran. */
  firstDay: DayKey;
  /** `sequence` walks the pool in order; `shuffle` deals it in a seeded order per cycle. @default 'sequence' */
  order?: 'sequence' | 'shuffle';
  /** Changes the shuffled order. @default 'daily' */
  seed?: string;
}

/**
 * Which item of a pool of `size` the day gets, or -1 for an empty pool or a
 * day before `firstDay`.
 */
export function dailyIndex(key: DayKey, size: number, options: DailyIndexOptions): number {
  const n = puzzleNumber(key, options.firstDay);
  if (size <= 0 || n < 1) return -1;
  const position = (n - 1) % size;
  if ((options.order ?? 'sequence') === 'sequence') return position;
  const cycle = Math.floor((n - 1) / size);
  const order = seededShuffle(
    Array.from({ length: size }, (_, i) => i),
    `${options.seed ?? 'daily'}:${cycle}`,
  );
  return order[position] as number;
}

/** The day's item from `pool`, or undefined when there is none. */
export function dailyItem<T>(pool: readonly T[], key: DayKey, options: DailyIndexOptions): T | undefined {
  const i = dailyIndex(key, pool.length, options);
  return i < 0 ? undefined : pool[i];
}

/**
 * Milliseconds until the next day starts in `timeZone`. On a day that a
 * clock change makes 23 or 25 hours long the answer can be off by that hour,
 * which is fine for a countdown and is why it is not used to pick puzzles.
 */
export function msUntilNextDay(now: Date | number = Date.now(), timeZone?: string): number {
  const date = typeof now === 'number' ? new Date(now) : now;
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(date);
  const part = Object.fromEntries(parts.map((p) => [p.type, Number(p.value)]));
  const elapsed =
    ((part.hour! * 60 + part.minute!) * 60 + part.second!) * 1000 + date.getMilliseconds();
  return DAY_MS - elapsed;
}

/**
 * @interlace/ui — games/daily
 *
 * The calendar under a daily game: which day it is for a player, which
 * puzzle that day gets, its number, and how long until the next one. Pure
 * functions, no React, no storage. Every component in `games/` builds on
 * these, and a server can call them too, so the puzzle a page renders and
 * the one a score is checked against come from the same arithmetic.
 *
 * ## Day keys
 *
 * A day is an ISO date string, `"2026-11-24"`, read in a time zone. Keys
 * sort as strings, survive JSON and storage unchanged, and compare without
 * a Date. Arithmetic on them runs in UTC, where every day has 24 hours, so
 * daylight-saving changes never skip or repeat a day.
 *
 * ## The puzzle of the day
 *
 * `dailyIndex` maps a day to an item in a pool. `order: 'sequence'` walks
 * the pool in order and starts again at the end. `order: 'shuffle'` deals
 * the pool in a seeded order that changes every cycle, and never repeats an
 * item inside a cycle. Both are deterministic: the same day, pool size and
 * seed give the same item on every device.
 */

/** An ISO calendar date, `YYYY-MM-DD`. */

import { addDays, daysBetween, isDayKey, weekdayOf, type DayKey } from '@/components/ui/games/daily';

/**
 * @interlace/ui — games/streak-model
 *
 * How long a player's run of days is, with rest days. Pure: give it the days
 * a player played and today's key; it returns the current run, the best run
 * and what each recent day was.
 *
 * ## Rest days
 *
 * A habit that punishes a day off teaches people to quit. `RestRule` names
 * days that never break a run: weekdays (`weekdays: [6]` rests every
 * Saturday) and dates (`dates: ['2026-12-25']`). A rest day the player skips
 * is passed over: the run neither grows nor ends. A rest day the player
 * plays anyway counts like any other day.
 *
 * ## Today is open
 *
 * Not having played yet today never ends a run; the day is still going. The
 * run ends only when a whole working day passes without a game. `status`
 * says which of these states the player is in, so a component can say
 * "play today to keep it" without working that out again.
 */

export interface RestRule {
  /** Weekdays that never break a run: 0 Sunday to 6 Saturday. */
  weekdays?: readonly number[];
  /** Single dates that never break a run, as day keys. */
  dates?: readonly DayKey[];
}

/**
 * - `played`: played today.
 * - `pending`: a run is alive and today still needs a game.
 * - `resting`: today is a rest day and has no game; the run is safe.
 * - `none`: no run to keep.
 */
export type StreakStatus = 'played' | 'pending' | 'resting' | 'none';

/** What one day was: played, rested, missed, today with no game yet, or not yet come. */
export type StreakDayState = 'played' | 'rest' | 'missed' | 'open' | 'future';

export interface StreakDay {
  day: DayKey;
  state: StreakDayState;
  /** True for today's key. */
  today: boolean;
}

export interface StreakSummary {
  /** Days played in the run that is still alive (0 when there is none). */
  current: number;
  /** The longest run on record, today's included. */
  best: number;
  status: StreakStatus;
  /** Total distinct days played up to today. */
  total: number;
}

/** True when the rule makes `day` a rest day. */
export function isRestDay(day: DayKey, rest?: RestRule): boolean {
  if (!rest) return false;
  if (rest.dates?.includes(day)) return true;
  return rest.weekdays?.includes(weekdayOf(day)) ?? false;
}

function playedSet(played: Iterable<DayKey>, today: DayKey): Set<DayKey> {
  const set = new Set<DayKey>();
  for (const day of played) {
    // A malformed key or a day after today (another device's clock) is ignored.
    if (isDayKey(day) && day <= today) set.add(day);
  }
  return set;
}

/** The player's current and best run, and where today stands. */
export function summarizeStreak(
  played: Iterable<DayKey>,
  today: DayKey,
  rest?: RestRule,
): StreakSummary {
  const days = playedSet(played, today);
  if (days.size === 0) {
    return { current: 0, best: 0, status: isRestDay(today, rest) ? 'resting' : 'none', total: 0 };
  }

  // One pass from the first game to today. A missed working day resets the
  // run; today never does, because it is still open.
  const first = [...days].sort()[0] as DayKey;
  const span = daysBetween(first, today);
  let run = 0;
  let best = 0;
  for (let i = 0; i <= span; i++) {
    const day = addDays(first, i);
    if (days.has(day)) run += 1;
    else if (day !== today && !isRestDay(day, rest)) run = 0;
    best = Math.max(best, run);
  }

  const playedToday = days.has(today);
  const status: StreakStatus = playedToday
    ? 'played'
    : isRestDay(today, rest)
      ? run > 0
        ? 'resting'
        : 'none'
      : run > 0
        ? 'pending'
        : 'none';
  return { current: run, best, status, total: days.size };
}

/**
 * The last `length` days ending today, oldest first, each with its state.
 * Pass `after` to also show days after today as `future` (a full week strip
 * that ends on Saturday, say).
 */
export function streakDays(
  played: Iterable<DayKey>,
  today: DayKey,
  options: { length?: number; after?: number; rest?: RestRule } = {},
): StreakDay[] {
  const { length = 7, after = 0, rest } = options;
  const days = playedSet(played, today);
  const out: StreakDay[] = [];
  for (let i = -(length - 1); i <= after; i++) {
    const day = addDays(today, i);
    const state: StreakDayState =
      i > 0
        ? 'future'
        : days.has(day)
          ? 'played'
          : isRestDay(day, rest)
            ? 'rest'
            : i === 0
              ? 'open'
              : 'missed';
    out.push({ day, state, today: i === 0 });
  }
  return out;
}
